def page(path,title,description,body,image,profile=False,extra=None):
 USED.setdefault(path,set()).add(image)
 graph=[{'@type':'WebSite','@id':BASE+'/#website','url':BASE+'/','name':'Jake Salerno'},PERSON,{'@type':'ProfilePage' if profile else 'CollectionPage' if path in ['/photos/','/media/','/event-features/'] else 'WebPage','@id':BASE+path+'#page','url':BASE+path,'name':title,'description':description,'mainEntity':{'@id':BASE+'/#person'} if profile else {'@id':BASE+path+'#collection'} if path in ['/photos/','/event-features/'] else {'@id':BASE+'/#person'},'about':{'@id':BASE+'/#person'},'isPartOf':{'@id':BASE+'/#website'},'primaryImageOfPage':{'@id':BASE+image+'#image'}}]
 if path in ['/photos/','/event-features/']:
  graph.append({'@type':'ItemList','@id':BASE+path+'#collection','itemListElement':[{'@type':'ListItem','position':n+1,'item':{'@id':BASE+p+'#image'}} for n,p in enumerate(sorted(USED[path]))]})
 for p in sorted(USED[path]):
  m=IMAGES[p];g={'@type':'ImageObject','@id':BASE+p+'#image','contentUrl':BASE+p,'url':BASE+p,'width':m['width'],'height':m['height'],'about':{'@id':BASE+'/#person'}}
  allitems=[(x,'/images/event-photos/') for x in DATA['eventPhotos']]+[(x,'/images/speaker-cards/') for x in DATA['speakerCards']]
  match=next((x for x,b in allitems if b+x['image']==p),None)
  if match:g['caption']=cap(match);g['name']=match.get('title',match.get('event'));g['description']=match.get('alt') or cap(match)
  if p in ['/images/event-photos/kbw-2026-speaking.webp','/images/event-photos/kbw-2026-panel.webp']:g['copyrightNotice']='@TOBY / MOMENTRIP'
  graph.append(g)
 if extra:graph.extend(extra)
 graph_json=json.dumps({"@context":"https://schema.org","@graph":graph},ensure_ascii=False).replace("<",chr(92)+"u003c")
 meta=f'''<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>{esc(title)}</title><meta name="description" content="{esc(description)}"><meta name="robots" content="index, follow, max-image-preview:large"><meta name="author" content="Jake Salerno"><link rel="canonical" href="{BASE+path}"><meta name="google-site-verification" content="RzuoUxwWvmyOm5ltR4Fwwgi673R-WRs4dz1LOaXzHOQ"><meta property="og:type" content="{'profile' if profile else 'website'}"><meta property="og:title" content="{esc(title)}"><meta property="og:description" content="{esc(description)}"><meta property="og:url" content="{BASE+path}"><meta property="og:site_name" content="Jake Salerno"><meta property="og:image" content="{BASE+image}"><meta property="og:image:width" content="{IMAGES[image]['width']}"><meta property="og:image:height" content="{IMAGES[image]['height']}"><meta property="og:image:alt" content="{esc(title)}"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:site" content="@JakeSalerno"><meta name="twitter:creator" content="@JakeSalerno"><meta name="twitter:title" content="{esc(title)}"><meta name="twitter:description" content="{esc(description)}"><meta name="twitter:image" content="{BASE+image}"><meta name="twitter:image:alt" content="{esc(title)}"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600&display=swap" rel="stylesheet"><link rel="stylesheet" href="/assets/site.css"><script type="application/ld+json">{graph_json}</script><script src="/assets/site.js" defer></script></head><body><a class="skip-link" href="#main">Skip to content</a>{NAV}<main id="main">{body}</main>{FOOTER}{DIALOG}</body></html>'''
 dest=ROOT/path.strip('/')/'index.html' if path!='/' else ROOT/'index.html';dest.parent.mkdir(parents=True,exist_ok=True);dest.write_text(meta);PAGES[path]={'title':title,'description':description,'image':image}

