 heroimg='/images/event-photos/token2049-singapore-speaking-closeup.webp'
 hero='''<section class="hero"><div class="hero-content"><div class="hero-text"><span class="hero-tag">AI infrastructure × go-to-market</span><h1>Jake Salerno</h1><p class="hero-description">Vice President of Go-to-Market at <strong>0G Labs</strong>, the trust layer for AI. Previously at Chainlink Labs. Building the teams, partnerships, and strategies that turn complex AI and blockchain infrastructure into products people and businesses use.</p><div class="hero-links">'''+link('Watch my talks','/#speaking','btn-primary')+link('Speaking & media inquiries','/#contact','btn-secondary')+'''</div><p class="social-links">'''+link('LinkedIn','https://www.linkedin.com/in/jakesalerno/')+' · '+link('X / @JakeSalerno','https://x.com/JakeSalerno')+'''</p></div><div class="hero-image-wrapper">'''+img(heroimg,'Jake Salerno speaking with expressive open-hand gestures at TOKEN2049 Singapore',True,'50% 40%')+'</div></div></section>'
