 page('/event-features/','Jake Salerno | Speaker cards & event features','Complete collection of speaker cards, conference appearances, and event announcements featuring Jake Salerno.','<section class="page-intro"><span class="section-label">Event features</span><h1>Speaker cards & event features</h1><p>Complete artwork, readable captions, and full-size images.</p></section>'+section('feature-archive','Full collection','Conferences & sessions',gallery(chronological(DATA['speakerCards']),'cards','/event-features/')),'/images/speaker-cards/dev-day-2026-speaker-card.webp')
 body='<section class="page-intro"><span class="section-label">Media archive</span><h1>Talks, interviews & conversations</h1><p>Recordings, interviews, podcasts, official session pages, and published coverage.</p></section>'+section('all-talks','Speaking','Talks & appearances',talks(chronological(DATA['speakingAppearances'])))
 for cat,label in [('press','Interviews & articles'),('conference','Official session & speaker pages'),('podcast','Podcasts & audio conversations'),('youtube','Video conversations'),('x-video','Recorded appearances')]:body+=section(cat,'Media',label,media(chronological([i for i in DATA['mediaResources'] if i['category']==cat])))
 page('/media/','Jake Salerno | Talks, interviews & media archive','Watch Jake Salerno’s talks and conversations, listen to podcasts, and read interviews about AI and blockchain infrastructure.',body,heroimg)
 for slug,a in APPEARANCES.items():
  path='/appearances/'+slug+'/'
