  if slug in ['ethcc-2026','token2049-2025'] or a.get('embedId'):
   vid=a.get('embedId') or ('2F9A0KsG7iI' if slug=='ethcc-2026' else 'og4yujmUPvk')
   summary+='<section class="reading"><h2>Watch the recording</h2><iframe class="recording-frame" src="https://www.youtube.com/embed/'+vid+'" title="'+esc(a['name'])+'" loading="lazy" allow="accelerometer; autoplay; encrypted-media; gyroscope; picture-in-picture" allowfullscreen></iframe></section>'
  relevant=[i for name in a['photos'] for i in DATA['eventPhotos'] if i['image']==name];cards=[i for name in a['cards'] for i in DATA['speakerCards'] if i['image']==name]
  images=(section('photographs','On stage','From the appearance',gallery(relevant,'photos',path)) if relevant else '')+(section('event-artwork','Event features','Session artwork',gallery(cards,'cards',path)) if cards else '')
  extra=[]
